// Custom word lists (v4.7) — user-authored decks, stored inside the
// schema-v2 profile under the additive `decks` key. Flutter-free so the
// whole CRUD surface is unit-testable without a widget tree.
//
// Design invariants (docs/ARCHITECTURE.md §4c):
// - Offline-only, no accounts: decks live and die with the profile
//   (load / save / export / import / resetAll).
// - Hard bounds keep the profile JSON small: 12 decks, 200 words per deck.
// - Tamper-proofing: load/import validate every field and silently drop
//   malformed entries; ids are re-generated by the store, never trusted.
// - Word ids never collide with course vocab ids (prefix `cd`, course ids
//   are `en_`/`fr_`/`ur_`), and stay stable once assigned (monotonic
//   counter survives deletions) so future per-word progress can key on them.

import 'models.dart'; // Vocab — custom words convert to Vocab for drills.

class CustomWord {
  final String id; // 'cd1_w3' — stable across deletions
  final String target; // word / phrase in the target language
  final String translationAr; // Arabic meaning
  final String? exampleTarget; // optional sentence in the target language
  final String? exampleAr; // optional Arabic sentence

  const CustomWord({
    required this.id,
    required this.target,
    required this.translationAr,
    this.exampleTarget,
    this.exampleAr,
  });

  Vocab toVocab(String deckId) => Vocab(
        id: id,
        target: target,
        translationAr: translationAr,
        exampleTarget: exampleTarget,
        exampleAr: exampleAr,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'target': target,
        'translationAr': translationAr,
        if (exampleTarget != null) 'exampleTarget': exampleTarget,
        if (exampleAr != null) 'exampleAr': exampleAr,
      };

  /// Strict parse — returns null for anything malformed. The stored id is
  /// validated against the deck prefix and kept verbatim (stable keys); a
  /// foreign or duplicated id is rejected by the caller's dedupe pass.
  static CustomWord? fromJson(Map<String, dynamic> j, String deckId) {
    final id = j['id'];
    if (id is! String ||
        !RegExp('^${RegExp.escape(deckId)}_w[0-9]+\$').hasMatch(id)) {
      return null;
    }
    final target = _clean(j['target'], maxLen: 60);
    final ar = _clean(j['translationAr'], maxLen: 80);
    if (target == null || ar == null) return null;
    final exT = _clean(j['exampleTarget'], maxLen: 120);
    final exA = _clean(j['exampleAr'], maxLen: 160);
    return CustomWord(
      id: id,
      target: target,
      translationAr: ar,
      exampleTarget: exT,
      exampleAr: exA,
    );
  }
}

class CustomDeck {
  final String id; // 'cd1'.. monotonic, assigned by the store
  final String name; // 1..40 chars, trimmed
  final String courseId; // 'en' | 'fr' | 'ur' | 'de'
  final List<CustomWord> words;

  /// Next word sequence for this deck — survives deletions so ids are
  /// never reused (stable keys for future progress tracking).
  final int nextSeq;

  const CustomDeck({
    required this.id,
    required this.name,
    required this.courseId,
    this.words = const [],
    this.nextSeq = 1,
  });

  CustomDeck copyWith({String? name, List<CustomWord>? words, int? nextSeq}) =>
      CustomDeck(
        id: id,
        name: name ?? this.name,
        courseId: courseId,
        words: words ?? this.words,
        nextSeq: nextSeq ?? this.nextSeq,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'courseId': courseId,
        'next': nextSeq,
        'words': words.map((w) => w.toJson()).toList(),
      };

  /// Strict parse — null for malformed decks. The stored id is re-validated
  /// against the `cd<digits>` shape so a foreign payload cannot collide with
  /// course content ids or break the monotonic counter.
  static CustomDeck? fromJson(Map<String, dynamic> j) {
    final id = j['id'];
    if (id is! String || !RegExp(r'^cd[0-9]+$').hasMatch(id)) return null;
    final name = _clean(j['name'], maxLen: 40);
    final course = j['courseId'];
    if (name == null) return null;
    if (course is! String || !['en', 'fr', 'ur', 'de'].contains(course)) {
      return null;
    }
    var maxSeq = 0;
    final words = <CustomWord>[];
    final seenWordIds = <String>{};
    if (j['words'] is List) {
      for (final raw in (j['words'] as List).take(maxWords)) {
        if (raw is! Map) continue;
        final w = CustomWord.fromJson(Map<String, dynamic>.from(raw), id);
        if (w == null || !seenWordIds.add(w.id)) continue; // dup rejected
        words.add(w);
        final m = RegExp(r'_w([0-9]+)$').firstMatch(w.id);
        if (m != null) {
          final s = int.parse(m.group(1)!);
          if (s > maxSeq) maxSeq = s;
        }
      }
    }
    final next = (j['next'] as num?)?.toInt() ?? 0;
    return CustomDeck(
      id: id,
      name: name,
      courseId: course,
      words: words,
      nextSeq: next > maxSeq ? next : maxSeq + 1,
    );
  }

  static const int maxWords = 200;
}

// ---------------- bounds & validation ----------------

class DeckLimits {
  static const int maxDecks = 12;

  /// Normalizes a user-entered name; null when unusable.
  static String? cleanName(String raw) => _clean(raw, maxLen: 40);

  /// Normalizes a user-entered word / meaning; null when unusable.
  static String? cleanWord(String raw, {int maxLen = 60}) =>
      _clean(raw, maxLen: maxLen);

  /// Case/punctuation-insensitive duplicate check key.
  static String dupKey(String s) => s
      .trim()
      .toLowerCase()
      .replaceAll(RegExp(r'[\p{P}\p{S}]', unicode: true), '')
      .replaceAll(RegExp(r'\s+'), ' ');
}

String? _clean(Object? raw, {required int maxLen}) {
  if (raw is! String) return null;
  final t = raw.trim().replaceAll(RegExp(r'[\u0000-\u001F\u007F]'), '');
  if (t.isEmpty || t.length > maxLen) return null;
  return t;
}
